`, "",{"version":3,"sources":["webpack://./src/views/privateViews/ArticleCreate.vue"],"names":[],"mappings":";AAoKA;IACI,aAAa;IACb,8BAA8B;IAC9B,mBAAmB;IACnB,mBAAmB;AACvB;AAEA;IACI,eAAe;IACf,iBAAiB;AACrB;AAEA;IACI,iBAAiB;IACjB,eAAe;AACnB","sourcesContent":["<script setup>\nimport { ref, reactive, computed, onMounted } from 'vue'\nimport { useRoute, useRouter } from 'vue-router'\nimport MarkdownCom from '@/components/MarkdownCom.vue'\nimport { ElMessage } from 'element-plus'\nimport {\n    requestArticleAdd,\n    requestArticleUpdate,\n    requestArticleDetail,\n    requestArticleCategoryList\n} from '@/composables/useRequest'\n\nconst route = useRoute()\nconst router = useRouter()\n\n// 编辑模式：路由带 id（query 优先，兼容 params）\nconst articleId = computed(() => {\n    const id = route.query.id ?? route.params.id\n    return id ? Number(id) : null\n})\nconst isEdit = computed(() => !!articleId.value)\n\nconst loading = ref(false)\nconst submitting = ref(false)\nconst categoryList = ref([])\n\nconst form = reactive({\n    title: '',\n    content: '',\n    category_ids: [],\n    status: 1 // 0-草稿，1-已发布，2-仅自己可见\n})\n\nconst statusOptions = [\n    { value: 0, label: '草稿' },\n    { value: 1, label: '已发布' },\n    { value: 2, label: '仅自己可见' }\n]\n\nconst getCategories = async () => {\n    try {\n        const res = await requestArticleCategoryList()\n        categoryList.value = res.data?.list || []\n    } catch (e) {\n        // 分类加载失败不阻塞编辑\n        console.error(e)\n    }\n}\n\nconst getDetail = async () => {\n    if (!articleId.value) return\n    loading.value = true\n    try {\n        const res = await requestArticleDetail(articleId.value)\n        const d = res.data || {}\n        form.title = d.title || ''\n        form.content = d.content || ''\n        form.category_ids = Array.isArray(d.category_ids) ? d.category_ids : []\n        form.status = d.status ?? 1\n    } catch (e) {\n        ElMessage.error(e?.response?.data?.message || '获取文章详情失败')\n    } finally {\n        loading.value = false\n    }\n}\n\nconst handleSubmit = async () => {\n    if (!form.title || !form.title.trim()) {\n        ElMessage.warning('请输入文章标题')\n        return\n    }\n    if (!form.content || !form.content.trim()) {\n        ElMessage.warning('请输入文章内容')\n        return\n    }\n    submitting.value = true\n    try {\n        const payload = {\n            title: form.title.trim(),\n            content: form.content,\n            category_ids: form.category_ids || [],\n            status: Number(form.status)\n        }\n        if (isEdit.value) {\n            await requestArticleUpdate(articleId.value, payload)\n            ElMessage.success('文章更新成功')\n        } else {\n            await requestArticleAdd(payload)\n            ElMessage.success('文章创建成功')\n        }\n        router.push('/article/article-manage')\n    } catch (e) {\n        ElMessage.error(e?.response?.data?.message || '提交失败')\n    } finally {\n        submitting.value = false\n    }\n}\n\nconst handleBack = () => {\n    router.push('/article/article-manage')\n}\n\nonMounted(() => {\n    getCategories()\n    getDetail()\n})\n</script>\n\n<template>\n    <div v-loading=\"loading\">\n        <div class=\"article-create-header\">\n            <span class=\"page-title\">{{ isEdit ? '编辑文章' : '写文章' }}</span>\n            <el-button @click=\"handleBack\">返回列表</el-button>\n        </div>\n\n        <el-form :model=\"form\" label-width=\"80px\">\n            <el-form-item label=\"标题\" required>\n                <el-input\n                    v-model=\"form.title\"\n                    placeholder=\"请输入文章标题\"\n                    maxlength=\"200\"\n                    show-word-limit\n                />\n            </el-form-item>\n\n            <el-form-item label=\"分类\">\n                <el-select\n                    v-model=\"form.category_ids\"\n                    multiple\n                    clearable\n                    placeholder=\"请选择分类（可多选）\"\n                    style=\"width: 100%\"\n                >\n                    <el-option\n                        v-for=\"c in categoryList\"\n                        :key=\"c.category_id\"\n                        :label=\"c.category_name\"\n                        :value=\"c.category_id\"\n                    />\n                </el-select>\n            </el-form-item>\n\n            <el-form-item label=\"状态\">\n                <el-radio-group v-model=\"form.status\">\n                    <el-radio v-for=\"s in statusOptions\" :key=\"s.value\" :value=\"s.value\">\n                        {{ s.label }}\n                    </el-radio>\n                </el-radio-group>\n            </el-form-item>\n\n            <el-form-item label=\"内容\" required>\n                <MarkdownCom v-model=\"form.content\" />\n            </el-form-item>\n        </el-form>\n\n        <div class=\"article-create-footer\">\n            <el-button type=\"primary\" size=\"large\" :loading=\"submitting\" @click=\"handleSubmit\">\n                {{ isEdit ? '保存修改' : '提交' }}\n            </el-button>\n        </div>\n    </div>\n</template>\n\n<style scoped>\n.article-create-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 20px;\n}\n\n.page-title {\n    font-size: 18px;\n    font-weight: bold;\n}\n\n.article-create-footer {\n    text-align: right;\n    margin-top: 8px;\n}\n</style>\n"],"sourceRoot":""}]);
