`, "",{"version":3,"sources":["webpack://./src/components/RolePermissionDialog.vue"],"names":[],"mappings":";AAiGA;IACI,aAAa;AACjB;AACA;IACI,cAAc;IACd,eAAe;AACnB;AACA;IACI,cAAc;IACd,kBAAkB;AACtB","sourcesContent":["<script setup>\nimport { ref, computed, watch } from 'vue'\nimport { ElMessage } from 'element-plus'\nimport {\n    requestPermissionList,\n    requestRolePermission,\n    requestRoleSetPermission\n} from '../composables/useRequest'\n\nconst props = defineProps({\n    modelValue: {\n        type: Boolean,\n        default: false\n    },\n    role: {\n        type: Object,\n        default: () => null\n    }\n})\n\nconst emit = defineEmits(['update:modelValue', 'success'])\n\nconst visible = computed({\n    get: () => props.modelValue,\n    set: (val) => emit('update:modelValue', val)\n})\n\nconst permissionList = ref([])\nconst checkedIds = ref([])\nconst loading = ref(false)\n\nconst loadData = async () => {\n    if (!props.role) return\n    loading.value = true\n    try {\n        const [permsRes, currentRes] = await Promise.all([\n            requestPermissionList(),\n            requestRolePermission(props.role.role_id)\n        ])\n        permissionList.value = permsRes.data.list || []\n        checkedIds.value = currentRes.data.permission_ids || []\n    } catch (e) {\n        ElMessage.error(e?.response?.data?.message || '加载权限失败')\n    } finally {\n        loading.value = false\n    }\n}\n\nwatch(\n    () => props.modelValue,\n    (val) => {\n        if (val) loadData()\n    }\n)\n\nconst save = async () => {\n    if (!props.role) return\n    loading.value = true\n    try {\n        await requestRoleSetPermission(props.role.role_id, checkedIds.value)\n        ElMessage.success('分配权限成功')\n        visible.value = false\n        emit('success')\n    } catch (e) {\n        ElMessage.error(e?.response?.data?.message || '分配权限失败')\n    } finally {\n        loading.value = false\n    }\n}\n</script>\n\n<template>\n    <el-dialog\n        :title=\"'分配权限 - ' + (role?.role_name || '')\"\n        v-model=\"visible\"\n        width=\"480px\"\n        align-center\n    >\n        <div v-loading=\"loading\">\n            <el-checkbox-group v-model=\"checkedIds\">\n                <div v-for=\"p in permissionList\" :key=\"p.permission_id\" class=\"perm-item\">\n                    <el-checkbox :value=\"p.permission_id\">\n                        {{ p.permission_name }}\n                        <span class=\"perm-desc\">（{{ p.permission_description }}）</span>\n                    </el-checkbox>\n                </div>\n            </el-checkbox-group>\n            <p v-if=\"permissionList.length === 0\" class=\"empty-tip\">暂无权限可分配</p>\n        </div>\n        <template #footer>\n            <el-button @click=\"visible = false\">取消</el-button>\n            <el-button type=\"primary\" :loading=\"loading\" @click=\"save\">保存</el-button>\n        </template>\n    </el-dialog>\n</template>\n\n<style scoped>\n.perm-item {\n    margin: 6px 0;\n}\n.perm-desc {\n    color: #909399;\n    font-size: 12px;\n}\n.empty-tip {\n    color: #909399;\n    text-align: center;\n}\n</style>\n"],"sourceRoot":""}]);
